('q_dej-pravek_7','Která změna znamenala přechod k usedlému životu?',ARRAY['vynález knihtisku','objev Ameriky','začátek zemědělství','příchod Slovanů']::TEXT[],2,'Neolit přinesl zemědělství.',3,ARRAY[]::TEXT[],NULL,7,'c_dej-pravek',NULL,NOW()),
('q_dej-pravek_8','Jak se jmenuje doba, kdy se lidé začali věnovat chovu zvířat a pěstování plodin?',ARRAY['doba železná','doba bronzová','neolit (mladší doba kamenná)','paleolit']::TEXT[],2,'Neolit je mladší doba kamenná.',3,ARRAY[]::TEXT[],NULL,8,'c_dej-pravek',NULL,NOW()),
